import {INITIAL_LAYOUT} from './initial-layout.js';
import {LayoutModel} from './model.js';
import {migrateFixtures} from './scene-items.js';
import {startEditor} from './app.js';
const key='moravian-exhibition-planner-v1',status=document.getElementById('storage-status');
const seed={version:1,vinylDefaultRevision:2,tastingPresetRevision:1,selected:null,items:new LayoutModel(INITIAL_LAYOUT.items).pack(),camera:{building:2,height:2.85,angle:-.65,tilt:.72,zoom:1,top:false,cut:true,roof:false,snap:true,court:false,installView:null,windowStudy:3,vinyl:INITIAL_LAYOUT.vinyl,sceneItems:migrateFixtures(INITIAL_LAYOUT.sceneItems)}};
let snapshot={modelContent:null,privateContent:seed};try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved?.privateContent?.version===1&&Array.isArray(saved.privateContent.items))snapshot=saved;}catch{status.textContent='저장 데이터를 읽지 못해 초기 배치를 표시합니다.';}
window.openai={widgetState:snapshot,setWidgetState:async next=>{window.openai.widgetState=next;try{localStorage.setItem(key,JSON.stringify(next));status.textContent='이 브라우저에 자동 저장됨';}catch{status.textContent='자동 저장 불가 · 배치 JSON을 파일로 보관하세요.';}}};
const app=startEditor();
const root=app.root,ui=k=>root.querySelector('[data-c="'+k+'"]');
// Native controls replace conversation-only carousel support.
for(const carousel of root.querySelectorAll('.viz-carousel')){const sections=Array.from(carousel.children).filter(n=>n.tagName==='SECTION'),nav=document.createElement('div');nav.className='viz-controls site-variants';const previous=document.createElement('button'),next=document.createElement('button'),select=document.createElement('select');previous.className=next.className='btn';previous.type=next.type='button';previous.textContent='이전 시안';next.textContent='다음 시안';select.className='form-select';select.setAttribute('aria-label','시트지 비교안');sections.forEach((s,i)=>select.add(new Option(s.dataset.variant,String(i))));let index=Math.max(0,sections.findIndex(s=>!s.hidden));function show(i){index=(i+sections.length)%sections.length;sections.forEach((s,j)=>s.hidden=j!==index);select.value=String(index);}previous.onclick=()=>show(index-1);next.onclick=()=>show(index+1);select.onchange=()=>show(Number(select.value));nav.append(previous,select,next);carousel.append(nav);show(index);}
for(const el of root.querySelectorAll('[data-tooltip]'))el.title=el.dataset.tooltip;
const download=document.createElement('button');download.type='button';download.className='btn';download.textContent='JSON 파일 저장';download.dataset.c='download';download.onclick=()=>{ui('export').click();const blob=new Blob([ui('json').value],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='moravian-layout.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
const label=document.createElement('label');label.className='btn';label.textContent='JSON 파일 불러오기';const input=document.createElement('input');input.type='file';input.accept='.json,application/json';input.hidden=true;input.dataset.c='upload';input.onchange=async()=>{const file=input.files?.[0];if(!file)return;try{if(file.size>1024*1024)throw Error('배치 파일은 1MB 이하로 선택하세요.');ui('json').value=await file.text();ui('import').click();}catch(e){ui('error').textContent=e.message;}input.value='';};label.append(input);ui('export').parentElement.append(download,label);
